(106, 'leads', 'lead-customer-inquiry-form-send', 'english', 'Lead customer inquiry form send', 'Inquiry Form', '<div>\r\n<div><span>Dear </span><span>{lead_name}</span><span>,</span></div>\r\n<div><span><br />I hope you\'re doing well. {product_description}</span><span><br /></span><span><br />Kindly complete it at your earliest convenience using the link below:<br /><br /></span><span>{inquiry_form_link}</span></div>\r\n<div><span>&nbsp; &nbsp; &nbsp; &nbsp; <br /></span><span>Please take a few minutes to fill out the form at your earliest convenience. Please feel free to reach out if you have any questions or require further assistance.<br /><br />Thank you for your prompt attention to this matter.</span></div>\r\n<div><span>&nbsp; &nbsp; &nbsp; &nbsp; </span></div>\r\n<div><span>{email_signature}</span></div>\r\n<div></div>\r\n</div>', '{companyname}', '', 0, 1, 0),
(107, 'leads', 'lead-customer-inquiry-form-not-approved', 'english', 'Lead customer inquiry form not approved', 'Inquiry Form Not Approved', '<div>\r\n<div><span>Dear </span><span>{lead_name}</span><span>,</span></div>\r\n<br />\r\n<div><span>&nbsp; &nbsp; &nbsp; &nbsp; Your form not approved due to {inquiry_form_not_approved_reason}. kindly please update the question answer on form using below link.</span></div>\r\n<div><span>&nbsp; &nbsp; &nbsp; &nbsp; </span></div>\r\n<div><span>Form Link : {inquiry_form_link}</span></div>\r\n<div><span>&nbsp; &nbsp; &nbsp; &nbsp; </span></div>\r\n<div><span>{email_signature}</span></div>\r\n</div>', '{companyname}', '', 0, 1, 0),
(108, 'leads', 'lead-customer-inquiry-form-approved', 'english', 'Lead customer inquiry form approved', 'Inquiry Form Approved', '<div><span>Dear </span><span>{lead_name}</span><span>,</span></div>\r\n<br />\r\n<div><span>&nbsp; &nbsp; &nbsp; &nbsp; Your form has been approved</span><span style=\"font-size: 12pt;\">.</span></div>\r\n<div><span>&nbsp; &nbsp; &nbsp; &nbsp; </span></div>\r\n<div><span>{email_signature}<br /></span></div>', '{companyname}', '', 0, 1, 0),
(109, 'vendors', 'vendor-quotation-form-approved', 'english', 'Vendor quotation form approved', 'Quotation Approved', '<div><span>Dear {vendor_name}</span><span>,</span></div>\r\n<br />\r\n<div><span>&nbsp; &nbsp; &nbsp; &nbsp; Your quotation form has been approved</span><span style=\"font-size: 12pt;\">.</span></div>\r\n<div><span>&nbsp; &nbsp; &nbsp; &nbsp; </span></div>\r\n<div><span>{email_signature}<br /></span></div>', '{companyname}', '', 0, 1, 0),
(110, 'vendors', 'vendor-quotation-form-not-approved', 'english', 'Vendor quotation form not approved', 'Quotation Not Approved', '<div>\r\n<div><span>Dear {vendor_name}</span><span>,</span></div>\r\n<br />\r\n<div><span>&nbsp; &nbsp; &nbsp; &nbsp; Your quotation form not approved due to {reject_note}. kindly please update the question answer on form using below link.</span></div>\r\n<div><span>&nbsp; &nbsp; &nbsp; &nbsp; </span></div>\r\n<div><span>Form Link : {quotation_form_link}</span></div>\r\n<div><span>&nbsp; &nbsp; &nbsp; &nbsp; </span></div>\r\n<div><span>{email_signature}</span></div>\r\n</div>', '{companyname}', '', 0, 1, 0),
(111, 'vendors', 'vendor-quotation-form-send', 'english', 'Vendor Quotation Form Send', 'Quotation Form', '<div>\r\n<div><span>Dear </span><span>{vendor_name}</span><span>,</span></div>\r\n<br />\r\n<div><span>&nbsp; &nbsp; &nbsp; &nbsp; I hope this message finds you well. Please fill the quotation form</span><span>. You can access the form through the following link: {quotation_form_link}</span></div>\r\n<div><span>&nbsp; &nbsp; &nbsp; &nbsp; </span></div>\r\n<div><span>&nbsp; &nbsp; &nbsp; &nbsp; Please let me know if there\'s anything else you need from me. I appreciate your assistance.</span></div>\r\n<div><span>&nbsp; &nbsp; &nbsp; &nbsp; </span></div>\r\n<div><span>{email_signature}</span></div>\r\n</div>', '{companyname}', '', 0, 1, 0),
(112, 'staff', 'reminder-customer-meeting-email-send', 'english', 'Reminder customer meeting email send', 'You Have a New Meeting Reminder!', '<p>Hello {customer_name},</p>\r\n<p>We have scheduled a meeting regarding <strong>{product_name}</strong> at <strong>{meeting_time}</strong> on <strong>{meeting_platform}&nbsp;</strong><br />Here is the meeting link: {meeting_link}.</p>\r\n<p>{email_signature}</p>', '{companyname}', '', 0, 1, 0),
(113, 'contract', 'contract-signed-otp-send', 'english', 'Agreement Sign OTP Verification', 'OTP for Agreement Sign', 'Hi<br /><br />Your one time password (OTP)&nbsp; <strong>{otp_code}&nbsp;</strong>for agreement sign at {companyname}<br /><br />This OTP is valid for 5 minutes only.', '{companyname}', '', 0, 1, 0),
(114, 'contract', 'contract-signed-to-partner', 'english', 'Agreement successfully signed by partner', 'Agreement successfully signed', 'Dear {contact_firstname} {contact_lastname}<br /><br />You successfully signed the agreement at {companyname}<br /><br />Thankyou<br />{companyname}', '{companyname}', '', 0, 1, 0),
(115, 'contract', 'contract-auth-otp-send', 'english', 'Agreement Authentication Email OTP Verification', 'OTP for Agreement Authentication', 'Hi<br /><br />Your one time password (OTP)&nbsp; <strong>{otp_code}&nbsp;</strong>for agreement authentication at {companyname}<br /><br />This OTP is valid for 5 minutes only.', '{companyname}', '', 0, 1, 0),
(116, 'leads', 'lead-customer-office-visit-form-otp-send', 'english', 'Lead customer office visit form otp send', 'OTP For Office Visit Form.', 'Hello, {lead_name}<br /><br />Here is your One time password (OTP) <strong>{otp_code}</strong> to fill visitor form at <strong>{companyname}</strong>', '{companyname}', '', 0, 1, 0),
(117, 'leads', 'lead-customer-office-visitor-form-send', 'english', 'Lead Customer Office Visitor form send', 'Visitor form', '<div><span>Dear </span><span>{lead_name}</span><span>,</span></div>\r\n<br />\r\n<div><span>Please fill-up office visit form.<br /><br /></span><span></span></div>\r\n<div><span>You can access the form through the following link: {visitor_form_link}</span></div>\r\n<div><span>&nbsp; &nbsp; &nbsp; &nbsp; </span></div>\r\n<div><span>Please take a few minutes to fill out the form at your earliest convenience. If you have any questions or require further assistance, please feel free to reach out.</span></div><br /><br />\r\n<div><span>{email_signature}</span></div>\r\n<div></div>', '{companyname}', '', 0, 1, 0),
(118, 'contract', 'send-verified', 'english', 'Agreement Successfully Verified', 'Agreement - {agreement_subject} Successfully Verified', '<p><span style=\"font-size: 12pt;\">Hi&nbsp;{contact_firstname}&nbsp;{contact_lastname}</span><br /><br /><span style=\"font-size: 12pt;\">Your Agreement {agreement_subject} verified successfully.<br /><br />Please find the attached PDF.</span><br /><br /><span style=\"font-size: 12pt;\">Kind Regards,</span><br /><span style=\"font-size: 12pt;\">{email_signature}</span></p>', '{companyname}', '', 0, 1, 0),
(119, 'contract', 'send-contract', 'english', 'Send Agreement to Customer', 'Agreement - {agreement_subject}', '<p><span style=\"font-size: 12pt;\">Hi&nbsp;{contact_firstname}&nbsp;{contact_lastname}</span><br /><br /><span style=\"font-size: 12pt;\">Below is agreement link. please sign it within 24 hours.<br /><br />Agreement Link : {agreement_link}<br /><br /></span><span style=\"font-size: 12pt;\">Looking forward to hear from you.</span><br /><br /><span style=\"font-size: 12pt;\">Kind Regards,</span><br /><span style=\"font-size: 12pt;\">{email_signature}</span></p>', '{companyname}', '', 0, 1, 0),
(120, 'leads', 'lead-new-mail-draft', 'english', 'Lead Customer New Email Draft', '', 'Hello, {lead_name}<br /><br />We have received your request for {product_name}<b></b>. How can we help you?', '{companyname}', '', 0, 1, 0),
(121, 'leads', 'lead-plant-visit-form-otp-send', 'english', 'Lead plant visit form otp send', 'OTP For Plant Visit Form.', 'Hello, {lead_name}<br /><br />Here is your One time password (OTP) <strong>{otp_code}</strong> to fill plant visit form at <strong>{companyname}</strong>', '{companyname}', '', 0, 1, 0),
(122, 'leads', 'lead-plant-visit-form-send', 'english', 'Lead plant visit form send', 'Plant Visit form', '<div><span>Dear </span><span>{lead_name}</span><span>,</span></div>\r\n<br />\r\n<div><span>Please fill-up plant visit form.<br /><br /></span><span></span></div>\r\n<div><span>You can access the form through the following link: {visitor_form_link}</span></div>\r\n<div><span>&nbsp; &nbsp; &nbsp; &nbsp; </span></div>\r\n<div><span>Please take a few minutes to fill out the form at your earliest convenience. If you have any questions or require further assistance, please feel free to reach out.</span></div><br /><br />\r\n<div><span>{email_signature}</span></div>\r\n<div></div>', '{companyname}', '', 0, 1, 0),
(123, 'leads', 'lead-plant-visit-form-approved', 'english', 'Lead plant visit form approved', 'Plant Visit Form Approved', '<div><span>Dear </span><strong>{lead_name}</strong><span>,</span></div>\r\n<br />\r\n<div><span>&nbsp; &nbsp; &nbsp; &nbsp; Your plant visit has been confirmed for <strong>{plant_visit_date_time}</strong> with total number of member <strong>{plant_visit_total_members}</strong>. Total payable amount for your visit is <strong>{plant_visit_payable_amount}</strong>.<br /></span></div>\r\n<div><span>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span></div>\r\n<div><span>{email_signature}<br /></span></div>', '{companyname}', '', 0, 1, 0),
(124, 'leads', 'lead-plant-visit-form-not-approved', 'english', 'Lead plant visit form not approved', 'Plant visit form not approved', '<div>\r\n<div><span>Dear </span><span>{lead_name}</span><span>,</span></div>\r\n<br />\r\n<div><span>&nbsp; &nbsp; &nbsp; &nbsp; Your plant visit form has been not approved due to <strong>{plant_visit_form_not_approved_reason}</strong>. kindly please update the form again using below link.</span></div>\r\n<div><span>&nbsp; &nbsp; &nbsp; &nbsp; </span></div>\r\n<div><span>Form Link : {plant_visit_form_link}</span></div>\r\n<div><span>&nbsp; &nbsp; &nbsp; &nbsp; </span></div>\r\n<div><span>{email_signature}</span></div>\r\n</div>', '{companyname}', '', 0, 1, 0),
(125, 'proposals', 'proposal-advance-payment-recorded', 'english', 'Proposal Advance Payment Recorded (Sent to Customer)', 'Payment Received', '<span style=\"font-size: 12pt;\">Hello <strong>{proposal_customer_name}</strong><br /><br /></span>Thank you for the payment. Find the payment details below:<br /><br />-------------------------------------------------<br /><br />Amount:&nbsp;<strong>{payment_total}<br /></strong>Date:&nbsp;<strong>{payment_date}</strong><br />Proposal number: <span style=\"font-size: 12pt;\"><strong># {proposal_number}<br /><br /></strong></span>-------------------------------------------------<br /><br />We are looking forward working with you.<br /><br /><span style=\"font-size: 12pt;\">Kind Regards,</span><br /><span style=\"font-size: 12pt;\">{email_signature}</span>', '{companyname}', '', 0, 1, 0),
(126, 'contract', 'payment-terms-reminder', 'english', 'Payment Terms Reminder', 'Payment Reminder For Your Agreement - {agreement_subject}', '<p><span style=\"font-size: 12pt;\">Hi {contact_firstname} {contact_lastname}</span><br /><br /><span style=\"font-size: 12pt;\">This is reminder for payment due of your agreement - <strong>{agreement_subject}</strong></span><br /><br /><span style=\"font-size: 12pt;\">Total Term Amount : <strong>{payment_term_amount} ({payment_term_percentage}% Of&nbsp; Total agreement amount)<br /></strong></span><span style=\"font-size: 12pt;\">Total Received Amount for Current Term : <strong><span style=\"color: #339966;\">{payment_term_received_amount}</span><br /></strong></span></p>\r\n<hr />\r\n<p><span style=\"font-size: 12pt;\">Due Amount for current term: <span style=\"color: #ff0000;\"><strong>{payment_term_due_amount}</strong></span></span><br /><span style=\"font-size: 12pt;\">Payment due date for current term : <span style=\"color: #ff0000;\"><strong>{payment_term_due_date}</strong></span></span><br /><br /><span style=\"font-size: 12pt;\">Kind Regards,</span><br /><span style=\"font-size: 12pt;\">{email_signature}</span></p>', '{companyname}', '', 0, 1, 0),
(127, 'contract', 'payment-terms-overdue-notice', 'english', 'Payment Terms Overdue Reminder', 'Payment Overdue Notice For Your Agreement - {agreement_subject}', '<p><span style=\"font-size: 12pt;\">Hi {contact_firstname} {contact_lastname}</span><br /><br /><span style=\"font-size: 12pt;\">This is an overdue notice for your agreement - <strong>{agreement_subject}</strong></span><br /><br /><span style=\"font-size: 12pt;\">Total Term Amount : <strong>{payment_term_amount} ({payment_term_percentage}% Of&nbsp; Total agreement amount)<br /></strong></span><span style=\"font-size: 12pt;\">Total Received Amount for Current Term : <strong><span style=\"color: #339966;\">{payment_term_received_amount}</span><br /></strong></span></p>\n<hr />\n<p><span style=\"font-size: 12pt;\">Due Amount for current term: <span style=\"color: #ff0000;\"><strong>{payment_term_due_amount}</strong></span></span><br /><span style=\"font-size: 12pt;\">Payment due date for current term : <span style=\"color: #ff0000;\"><strong>{payment_term_due_date}</strong></span></span><br /><br /><span style=\"font-size: 12pt;\">Kind Regards,</span><br /><span style=\"font-size: 12pt;\">{email_signature}</span></p>', '{companyname}', '', 0, 1, 0),
(128, 'leads', 'leads-form-brochure-download', 'english', 'Lead Form Brochure Download', '{companyname} - Brochure', '<div>Hello</div>\r\n<div><span><br />Thank you for Contact Us.<br />You can download the Brochure from below link.<br /><br />{company_brochure_link}<br /></span></div>', '{companyname}', '', 0, 1, 0),
(129, 'goals', 'goals-failed-to-achieve', 'english', 'Goal failed to achieve', 'Goal Achievement Update', '<p>Hello <strong>{staff_firstname} {staff_lastname}</strong>,</p>\r\n<p>We regret to inform you that you did not meet the goal set. Below is an overview of your goal progress:</p>\r\n<p><strong>Your Goal Progress Details :</strong></p>\r\n<ul>\r\n<li><strong>Goal Period</strong>: {goal_duration_period}</li>\r\n<li><strong>Goal Target</strong>: {goal_target}</li>\r\n<li><strong>Goal Achieved</strong>: {goal_achievement}</li>\r\n</ul>\r\n<p><strong>Goal Details :</strong></p>\r\n<ul>\r\n<li><strong>Goal Subject</strong>: {goal_subject}</li>\r\n<li><strong>Goal Description</strong>: {goal_description}</li>\r\n<li><strong>Goal Type</strong>: {goal_type}</li>\r\n<li><strong>Goal Duration Type</strong>: {goal_duration_type}</li>\r\n</ul>\r\n<br />We encourage you to try to improve next time, and we believe you will achieve even better results moving forward.', '{companyname}', '', 0, 1, 0),
(130, 'goals', 'goals-achieve', 'english', 'New goal achieved', 'Congratulations on Achieving Your Goal!', '<p>Hello {staff_firstname} {staff_lastname},</p>\r\n<p>We are pleased to inform you that you successfully achieved your goal. Below is a summary of your outstanding performance:</p>\r\n<p><strong>Your Goal Achievement Details</strong></p>\r\n<ul>\r\n<li><strong>Goal Period</strong>: {goal_duration_period}</li>\r\n<li><strong>Goal Target</strong>: {goal_target}</li>\r\n<li><strong>Goal Achieved</strong>: {goal_achievement}</li>\r\n</ul>\r\n<p><strong>Goal Details</strong></p>\r\n<ul>\r\n<li><strong>Goal Subject</strong>: {goal_subject}</li>\r\n<li><strong>Goal Description</strong>: {goal_description}</li>\r\n<li><strong>Goal Type</strong>: {goal_type}</li>\r\n<li><strong>Goal Duration Type</strong>: {goal_duration_type}</li>\r\n</ul>\r\n<p>Congratulations on this achievement! We appreciate your hard work and dedication. Keep up the great work!</p>', '{companyname}', '', 0, 1, 0),
(131, 'goals', 'goals-new-assigned', 'english', 'New goal assigned', 'New goal assigned to you', '<div>Hello <strong>{staff_firstname} {staff_lastname}</strong>,<br /><br />New goal assigned you...<br /><br /><strong>Goal Subject :</strong> {goal_subject} &nbsp; &nbsp; &nbsp; &nbsp;<br /><br /><strong>Goal Description :</strong> {goal_description}<br /><br /><strong>Goal Type :</strong> {goal_subject}<br /><br /><strong>Goal Target : </strong>{goal_target} &nbsp; &nbsp; &nbsp; &nbsp;<br /><br /><strong>Goal Duration : </strong>{goal_duration_type}&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</div>', '{companyname}', '', 0, 1, 0),
(132, 'contract', 'send-contract-vendor', 'english', 'Send Agreement to Vendor', 'Agreement - {agreement_subject}', '<p><span style=\"font-size: 12pt;\">Hi {vendor_name}</span><br /><br /><span style=\"font-size: 12pt;\">Below is agreement link. please sign it within 24 hours.<br /><br />Agreement Link : {agreement_link}<br /><br /></span><span style=\"font-size: 12pt;\">Looking forward to hear from you.</span><br /><br /><span style=\"font-size: 12pt;\">Kind Regards,</span><br /><span style=\"font-size: 12pt;\">{email_signature}</span></p>', '{companyname}', '', 0, 1, 0),
(133, 'contract', 'contract-signed-to-vendor', 'english', 'Agreement successfully signed by vendor', 'Agreement successfully signed', 'Dear {vendor_name} <br /><br />You successfully signed the agreement at {companyname}<br /><br />Thankyou<br />{companyname}', '{companyname}', '', 0, 1, 0),
(134, 'contract', 'send-verified-vendor', 'english', 'Agreement Successfully Verified (For Vendor)', 'Agreement - {agreement_subject} Successfully Verified', '<p><span style=\"font-size: 12pt;\">Hi&nbsp;{vendor_name}</span><br /><br /><span style=\"font-size: 12pt;\">Your Agreement {agreement_subject} verified successfully.<br /><br />Please find the attached PDF.</span><br /><br /><span style=\"font-size: 12pt;\">Kind Regards,</span><br /><span style=\"font-size: 12pt;\">{email_signature}</span></p>', '{companyname}', '', 0, 1, 0),
(135, 'leads-follow-up', 'leads-follow-up-1', 'english', 'Template 1 : Initial Follow-Up After Inquiry ', '', '', '{companyname}', '', 0, 1, 0),
