(145, 'purchase', 'purchase-email-send-to-vendor', 'english', 'Purchase Email Send To Vendor', 'Purchase Order ', '<p data-start=\"165\" data-end=\"184\">Dear <strong>{purchase_to}</strong>,</p>\r\n<p data-start=\"186\" data-end=\"256\">Please find attached the Purchase Order #<strong>{purchase_number}</strong> for your reference.<br /><br /><span>{email_signature}</span></p>', '{companyname}', '', 0, 1, 0),
(146, 'debit_note', 'debit-note-send-to-vendor', 'english', 'Send Debit Note To Email', 'Debit Note With Number #{debit_note_number} Created', 'Dear {vendor_name}<br /><br />We have attached the debit note with number <strong>#{debit_note_number} </strong>for your reference.<br /><br /><strong>Date:</strong>&nbsp;{debit_note_date}<br /><strong>Total Amount:</strong>&nbsp;{debit_note_total}<br /><br /><span style=\"font-size: 12pt;\">Please contact us for more information.</span><br /><br /><span style=\"font-size: 12pt;\">Kind Regards,</span><br /><span style=\"font-size: 12pt;\">{email_signature}</span>', '{companyname}', '', 0, 1, 0),
(147, 'contract', 'send-contract-contact-book-user', 'english', 'Send Agreement to Contact Book User', 'Agreement - {agreement_subject}', '<p><span style=\"font-size: 12pt;\">Hi <strong>{contact_book_firstname} {contact_book_lastname}</strong></span><br /><br /><span style=\"font-size: 12pt;\">Below is agreement link. please sign it within 24 hours.<br /><br />Agreement Link : {agreement_link}<br /><br /></span><span style=\"font-size: 12pt;\">Looking forward to hear from you.</span><br /><br /><span style=\"font-size: 12pt;\">Kind Regards,</span><br /><span style=\"font-size: 12pt;\">{email_signature}</span></p>', '{companyname}', '', 0, 1, 0),
(148, 'contract', 'contract-signed-to-contact-book-user', 'english', 'Agreement successfully signed by Contact Book User', 'Agreement successfully signed', '<span style=\"font-size: 12pt;\">Hi <strong>{contact_book_firstname} {contact_book_lastname}</strong></span><br /><br />You successfully signed the agreement at {companyname}<br /><br />Thankyou<br />{companyname}', '{companyname}', '', 0, 1, 0),
(149, 'contract', 'send-contract-verified-to-contact-book-user', 'english', 'Agreement Successfully Verified (For Contact Book User)', 'Agreement - {agreement_subject} Successfully Verified', '<p><span style=\"font-size: 12pt;\">Hi <strong>{contact_book_firstname} {contact_book_lastname}</strong></span><br /><br /><span style=\"font-size: 12pt;\">Your Agreement {agreement_subject} verified successfully.<br /><br />Please find the attached PDF.</span><br /><br /><span style=\"font-size: 12pt;\">Kind Regards,</span><br /><span style=\"font-size: 12pt;\">{email_signature}</span></p>', '{companyname}', '', 0, 1, 0),
(150, 'contract', 'contract-expiration-to-vendor', 'english', 'Agreement Expiration Reminder (Sent to Vendor)', 'Agreement Expiration Reminder', '<span style=\"font-size: 12pt;\">Dear {vendor_name}</span><br /><br /><span style=\"font-size: 12pt;\">This is a reminder that the following contract will expire soon:</span><br /><br /><span style=\"font-size: 12pt;\"><strong>Subject:</strong> {agreement_subject}</span><br /><span style=\"font-size: 12pt;\"><strong>Description:</strong> {agreement_description}</span><br /><span style=\"font-size: 12pt;\"><strong>Date Start:</strong> {agreement_datestart}</span><br /><span style=\"font-size: 12pt;\"><strong>Date End:</strong> {agreement_dateend}</span><br /><br /><span style=\"font-size: 12pt;\">Please contact us for more information.</span><br /><br /><span style=\"font-size: 12pt;\">Kind Regards,</span><br /><span style=\"font-size: 12pt;\">{email_signature}</span>', '{companyname} | CRM', '', 0, 1, 0),
(151, 'contract', 'contract-expiration-to-contact-book-user', 'english', 'Agreement Expiration Reminder (Sent to Contact Book user)', 'Agreement Expiration Reminder', '<span style=\"font-size: 12pt;\">Dear {contact_book_firstname} {contact_book_lastname}</span><br /><br /><span style=\"font-size: 12pt;\">This is a reminder that the following contract will expire soon:</span><br /><br /><span style=\"font-size: 12pt;\"><strong>Subject:</strong> {agreement_subject}</span><br /><span style=\"font-size: 12pt;\"><strong>Description:</strong> {agreement_description}</span><br /><span style=\"font-size: 12pt;\"><strong>Date Start:</strong> {agreement_datestart}</span><br /><span style=\"font-size: 12pt;\"><strong>Date End:</strong> {agreement_dateend}</span><br /><br /><span style=\"font-size: 12pt;\">Please contact us for more information.</span><br /><br /><span style=\"font-size: 12pt;\">Kind Regards,</span><br /><span style=\"font-size: 12pt;\">{email_signature}</span>', '{companyname} | CRM', '', 0, 1, 0),
(152, 'contract', 'contract-comment-to-vendor', 'english', 'New Comment (Sent to Vendor)', 'New Agreement Comment', 'Dear {vendor_name}<br /><br />A new comment has been made on the following agreement: <strong>{agreement_subject}</strong><br /><br />You can view and reply to the comment on the following link: {agreement_link}<br /><br />Kind Regards,<br />{email_signature}', '{companyname}', '', 0, 1, 0),
(153, 'contract', 'contract-expiration-to-contact-book-user', 'english', 'New Comment (Sent to Contact Book User)', 'New Agreement Comment', 'Dear {contact_book_firstname} {contact_book_lastname}<br /><br />A new comment has been made on the following agreement: <strong>{agreement_subject}</strong><br /><br />You can view and reply to the comment on the following link: {agreement_link}<br /><br />Kind Regards,<br />{email_signature}', '{companyname}', '', 0, 1, 0);
